\title{Central Gaussian Coefficients and the Maximal Binary 2-Binomial Class}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
We study the sizes of the \emph{2-binomial equivalence classes} of binary words
and their identification, via MacMahon's theorem, with the coefficients of the
Gaussian ($q$-)binomial coefficients. Two binary words are 2-binomially equivalent
(Rigo--Salimov) when they contain the same number of scattered occurrences of every
factor of length at most two; for the binary alphabet this is equivalent to sharing
the same length $n$, the same number of ones $k$, and the same inversion number $i$
(scattered occurrences of $10$). Indexing a class by $(n,k,i)$, its cardinality
$\classSize(n,k,i)$ equals the coefficient of $q^i$ in $\qbin{n}{k}$. Modeling a
word by the $k$-element set of positions of its ones, we establish the ceiling
$\invF \le k(n-k)$, vanishing beyond the ceiling, the row sum
$\sum_i \classSize(n,k,i) = \binom{n}{k}$, and the palindromic symmetry
$\classSize(n,k,i) = \classSize(n,k,k(n-k)-i)$ via a word-reversal bijection
interchanging inversions and co-inversions; the symmetry yields that the mean
inversion number is the central index $k(n-k)/2$. The headline statement that the
central coefficient is the global maximum is full unimodality of Gaussian binomials
(Sylvester 1878; first elementary proof O'Hara 1990); we verify it as certified
results for all $n \le 8$ by exhaustive computation and record the general case and
related identities as conjectures.
\end{abstract}

\section{Introduction}

\subsection{Binomial equivalence of words}
For words $u,w$ over an alphabet $A$, the \emph{binomial coefficient}
$\binom{w}{u}$ counts occurrences of $u$ as a scattered subword of $w$. Words
$w,w'$ are \emph{$m$-binomially equivalent}, $w \sim_m w'$, when
$\binom{w}{u} = \binom{w'}{u}$ for every $u$ with $|u| \le m$. For the binary
alphabet and $m=2$, the relevant data are $k$ (number of ones), $n=|w|$, and the
length-two counts; using $\binom{w}{11}=\binom{k}{2}$, $\binom{w}{00}=\binom{n-k}{2}$,
and $\binom{w}{10}+\binom{w}{01}=k(n-k)$, a binary 2-binomial class is determined by
$$ (n,k,i), \qquad i := \binom{w}{10} = \#\{(a,b): a<b,\ w_a=1,\ w_b=0\}, $$
the \emph{inversion number} of $w$.

\subsection{The Gaussian connection}
The \emph{Gaussian binomial coefficient} is
$$ \qbin{n}{k} = \prod_{j=1}^{k}\frac{1-q^{\,n-k+j}}{1-q^{\,j}}, $$
a polynomial in $q$ of degree $k(n-k)$ with nonnegative integer coefficients.
MacMahon's theorem gives
$$ \qbin{n}{k} = \sum_{i\ge 0} \classSize(n,k,i)\, q^i, $$
where $\classSize(n,k,i)$ counts binary words of length $n$ with $k$ ones and
inversion number $i$. Thus the enumerative and algebraic questions coincide.

\subsection{Model}
We use $\Fin n = \{0,\dots,n-1\}$ as positions. A word of length $n$ with $k$ ones
is encoded by the set $S\subseteq \Fin n$ of one-positions, $|S|=k$; the set of such
words then has cardinality $\binom{n}{k}$.

\section{Definitions}

\begin{definition}[Inversion number]
For $S \subseteq \Fin n$,
$$ \invF(S) := \#\{(p_1,p_2)\in \Fin n\times \Fin n : p_1<p_2,\ p_1\in S,\ p_2\notin S\}. $$
\end{definition}

\begin{definition}[Co-inversion number]
$$ \coinvF(S) := \#\{(p_1,p_2): p_1<p_2,\ p_1\notin S,\ p_2\in S\}. $$
\end{definition}

\begin{definition}[Words]
$\words(n,k) := \{S\subseteq \Fin n : |S|=k\}$.
\end{definition}

\begin{definition}[Class size]
$\classSize(n,k,i) := \#\{S\in\words(n,k) : \invF(S)=i\}$, the coefficient of $q^i$
in $\qbin{n}{k}$.
\end{definition}

\begin{definition}[Central index]
$\mathrm{centralIndex}(n,k) := \lfloor k(n-k)/2\rfloor$.
\end{definition}

\section{Main Results}

\begin{theorem}[\texttt{invF\_le}]\label{thm:le}
For every $S\subseteq \Fin n$ with $|S|=k$, $\invF(S) \le k(n-k)$.
\end{theorem}
\begin{proof}[Proof sketch]
Each counted pair $(p_1,p_2)$ has $p_1\in S$, $p_2\in \Fin n\setminus S$, so the
inversions inject into $S\times(\Fin n\setminus S)$, of size $k(n-k)$; the
constraint $p_1<p_2$ only removes pairs.
\end{proof}

\begin{corollary}[\texttt{classSize\_eq\_zero\_of\_gt}]
If $k(n-k)<i$ then $\classSize(n,k,i)=0$.
\end{corollary}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:le} the defining filter is empty.
\end{proof}

\begin{theorem}[\texttt{total\_eq\_choose}]\label{thm:total}
$\displaystyle \sum_{i=0}^{k(n-k)} \classSize(n,k,i) = \binom{n}{k}$.
\end{theorem}
\begin{proof}[Proof sketch]
The fibers $\{S : \invF(S)=i\}$ partition $\words(n,k)$ as $i$ ranges over
$\{0,\dots,k(n-k)\}$ (Theorem~\ref{thm:le}); summing fiber cardinalities over a
partition recovers $|\words(n,k)| = \binom{n}{k}$, since $\words(n,k)$ is the set of
$k$-subsets of an $n$-set. This is the $q=1$ specialization of MacMahon's theorem.
\end{proof}

\begin{lemma}[\texttt{invF\_image\_rev}]\label{lem:rev}
Let $\rev(p)=n-1-p$. Then $\invF(\rev(S)) = \coinvF(S)$.
\end{lemma}
\begin{proof}[Proof sketch]
The map $(p_1,p_2)\mapsto(\rev(p_2),\rev(p_1))$ bijects the co-inversions of $S$
with the inversions of $\rev(S)$: it reverses order and swaps the membership
conditions.
\end{proof}

\begin{lemma}[\texttt{invF\_add\_coinvF}]\label{lem:add}
For $|S|=k$, $\invF(S)+\coinvF(S) = k(n-k)$.
\end{lemma}
\begin{proof}[Proof sketch]
Inversions and co-inversions are disjoint, and their union is the set of ordered
pairs $p_1<p_2$ with exactly one position in $S$. Each unordered mixed pair
contributes one ordered pair, so the union has size
$|S\times(\Fin n\setminus S)| = k(n-k)$.
\end{proof}

\begin{theorem}[\texttt{classSize\_symm}]\label{thm:symm}
For $i\le k(n-k)$, $\classSize(n,k,i) = \classSize(n,k,\,k(n-k)-i)$.
\end{theorem}
\begin{proof}[Proof sketch]
$S\mapsto\rev(S)$ is a cardinality-preserving involution of $\words(n,k)$. By
Lemmas~\ref{lem:rev} and~\ref{lem:add}, $\invF(S)=i$ implies
$\invF(\rev(S)) = \coinvF(S) = k(n-k)-i$, so $\rev$ bijects the class at $i$ with
the class at $k(n-k)-i$.
\end{proof}

\begin{corollary}[Mean inversion number, \texttt{inv\_weighted\_sum}]
Under the uniform distribution on $\words(n,k)$,
$\E[\invF] = \frac{1}{\binom{n}{k}}\sum_i i\,\classSize(n,k,i) = \frac{k(n-k)}{2}$.
\end{corollary}
\begin{proof}[Proof sketch]
For the reversal involution, $\invF(S)+\invF(\rev(S)) = k(n-k)$
(Lemmas~\ref{lem:rev},\ref{lem:add}); averaging $\invF$ over the
involution-invariant uniform measure gives $k(n-k)/2$. Equivalently, pair each term
$i$ with its mirror $k(n-k)-i$ in Theorem~\ref{thm:symm}.
\end{proof}

\begin{theorem}[\texttt{central\_max\_*}, verified for $n\le 8$]
For every $n\le 8$, every $0\le k\le n$, and every $i$,
$$ \classSize(n,k,i) \le \classSize\bigl(n,k,\lfloor k(n-k)/2\rfloor\bigr). $$
\end{theorem}
\begin{proof}[Status and method]
This is central maximality of $\qbin{n}{k}$, a case of the unimodality of Gaussian
binomials (Sylvester 1878 via invariant theory; representation-theoretically via the
$\mathfrak{sl}_2$-action / hard Lefschetz; first elementary proof O'Hara 1990). The
general statement is not proved here. For each fixed $n\le 8$ the inequality is a
finite assertion over the finite set $\words(n,k)$ and is decided by exhaustive
certified computation. The general case is Conjecture~\ref{conj:c1}.
\end{proof}

\section{Algorithms}
\textbf{Direct computation.} Enumerate the $\binom{n}{k}$ subsets and tabulate
inversion numbers; a left-to-right scan computes $\invF$ in $O(n)$ per word, giving a
full row in $O(n\binom{n}{k})$.

\textbf{$q$-Pascal recurrence.} Conditioning on the last letter
(Conjecture~\ref{conj:c2}) gives a dynamic program over the triangle
$\classSize(n,k,i)$.

\textbf{Box partitions.} By Conjecture~\ref{conj:c3}, $\classSize(n,k,i)$ counts
partitions of $i$ into at most $k$ parts, each at most $n-k$.

\section{Applications}
\textbf{Statistical mechanics.} With inversion number as energy, $\qbin{n}{k}$ is a
partition function ($q=e^{-\beta\epsilon}$) and $\classSize(n,k,i)$ the degeneracy of
level $i$; central maximality means the modal energy equals the mean $k(n-k)/2$.

\textbf{Concentration.} The inversion statistic has mean $k(n-k)/2$ and conjecturally
variance $k(n-k)(n+1)/12$, giving a sharply peaked symmetric discrete law.

\textbf{$q$-analogues.} Over $\mathbb{F}_q$, $\qbin{n}{k}$ counts $k$-subspaces of
$\mathbb{F}_q^n$, linking these statistics to finite geometry and quantum groups.

\section{Future Directions}

\begin{conjecture}[Full unimodality]\label{conj:c1}
For all $n,k,i$, $\classSize(n,k,i)\le\classSize(n,k,\lfloor k(n-k)/2\rfloor)$, and
$i\mapsto\classSize(n,k,i)$ is unimodal.
\end{conjecture}

\begin{conjecture}[$q$-Pascal recurrence]\label{conj:c2}
For $0<k\le n$ and $k\le i$,
$\classSize(n+1,k,i) = \classSize(n,k-1,i) + \classSize(n,k,i-k)$, with boundary
$\classSize(n+1,k,i)=\classSize(n,k-1,i)$ when $i<k$.
\end{conjecture}

\begin{conjecture}[Partition-in-a-box]\label{conj:c3}
$\classSize(n,k,i)$ equals the number of partitions of $i$ into at most $k$ parts,
each at most $n-k$.
\end{conjecture}

\begin{conjecture}[Strict unimodality and log-concavity]
For $0<k<n$, the sequence strictly increases on $0\le i\le k(n-k)/2$, and
$\classSize(n,k,i)^2 \ge \classSize(n,k,i-1)\,\classSize(n,k,i+1)$.
\end{conjecture}

\begin{conjecture}[Variance]
With $\mu=k(n-k)/2$,
$12\sum_i (i-\mu)^2\,\classSize(n,k,i) = k(n-k)(n+1)\binom{n}{k}$, i.e. the inversion
variance is $k(n-k)(n+1)/12$.
\end{conjecture}

\section{Conclusion}
The binary 2-binomial class $(n,k,i)$ has size equal to the $q^i$-coefficient of
$\qbin{n}{k}$. We proved boundedness, vanishing, summation to $\binom{n}{k}$, and
palindromic symmetry (with a reversal bijection at the core), and derived the mean
inversion number $k(n-k)/2$. Central maximality is the deep unimodality of Gaussian
binomials, certified here for $n\le 8$, with a concrete program toward the general
result.

