function ClassRowLinearScan(n, k):
    row <- array of zeros, length k*(n-k)+1
    for each k-subset P of {0..n-1}:
        seen_ones <- 0; inv <- 0
        for p from 0 to n-1:
            if p in P: seen_ones <- seen_ones + 1
            else:      inv <- inv + seen_ones
        row[inv] <- row[inv] + 1
    return row
